from content_common import *
import sysrev, json

def build(b, N):
    refs = json.load(open(os.path.join(HERE, "..", "data", "refs_master.json")))["refs"]
    # ------------------------------------------------ 2.5
    b.h2("2.5 กลศาสตร์ของกำลังอัดและความหนาแน่นของบล็อกอัดแน่น")
    b.h3("2.5.1 ความสัมพันธ์ระหว่างกำลังอัดกับความพรุนและความหนาแน่น")
    b.p("กำลังอัดของวัสดุซีเมนต์ลดลงเมื่อความพรุน (p) เพิ่มขึ้น มีแบบจำลองเชิงประจักษ์คลาสสิกสามรูปแบบที่ใช้กันทั่วไป ได้แก่ แบบ Balshin ที่ถือว่ากำลังแปรตามส่วนที่เป็นของแข็ง (1 − p) ยกกำลัง n แบบ Ryshkewitch ที่ถือว่ากำลังลดแบบเอกซ์โปเนนเชียลตามความพรุน และแบบ Schiller ที่ใช้ลอการิทึม Chen และคณะ (2013) {c:chenx2013} ใช้ข้อมูลมอร์ตาร์ทดสอบแบบจำลองเหล่านี้กับกำลังอัดและกำลังดึงแบบผ่า Kumar และ Bhattacharjee (2003) {c:kumar2003} พบว่าความสัมพันธ์ที่สร้างจากเพสต์หรือมอร์ตาร์ไม่เพียงพอสำหรับคอนกรีต จึงเสนอแบบจำลองที่เพิ่มเงื่อนไขขนาดรูพรุน ปริมาณซีเมนต์ ชนิดมวลรวม และสภาวะแวดล้อม ส่วน Lian และคณะ (2011) {c:lian2011} พัฒนาแบบจำลองกำลังอัดเทียบกับความพรุนสำหรับคอนกรีตพรุน")
    b.eq("balshin", r"f_{c} = f_{c0}\left(1-p\right)^{n}")
    b.eq("ryshkewitch", r"f_{c} = f_{c0}\,e^{-bp}")
    b.eq("schiller", r"f_{c} = D\,\ln\left(\frac{p_{cr}}{p}\right)")
    b.p("โดยที่ f<sub>c</sub> คือกำลังอัด f<sub>c0</sub> คือกำลังอัดที่ความพรุนเป็นศูนย์ p คือความพรุน (สัดส่วนปริมาตร) p<sub>cr</sub> คือความพรุนวิกฤตที่กำลังเป็นศูนย์ และ n b D เป็นค่าคงที่ที่ต้องปรับให้เข้ากับข้อมูลแต่ละชนิดวัสดุ ในงานนี้ไม่ได้วัดความพรุนโดยตรง จึงใช้ความหนาแน่นสัมพัทธ์แทน เนื่องจากส่วนที่เป็นของแข็งแปรตามความหนาแน่นเมื่อองค์ประกอบของแข็งใกล้เคียงกัน ได้รูปแบบกำลังยกกำลังของความหนาแน่นสัมพัทธ์ดังสมการที่ {eq:reldens} และปรับค่า n จากข้อมูลในหัวข้อ 4.3.4")
    b.eq("reldens", r"\frac{f_{c}}{f_{c,ref}} = \left(\frac{\rho}{\rho_{ref}}\right)^{n}")
    b.p("ข้อควรระวังคือความหนาแน่นสัมพัทธ์ของสูตรต่างกันสะท้อนทั้งความพรุนและความแตกต่างของวัสดุ (ไบโอชาร์มีความหนาแน่นอนุภาคต่ำกว่าซีเมนต์) การตีความค่า n จึงใช้ได้เฉพาะเป็นดัชนีความไวของกำลังต่อความหนาแน่นภายในงานนี้ ไม่ควรเทียบกับค่าคงที่ของวัสดุอื่นโดยตรง")
    b.h3("2.5.2 การพัฒนากำลังตามอายุ")
    b.p("การพัฒนากำลังอัดตามอายุของคอนกรีตมักแสดงด้วยแบบจำลองความแก่ในมาตรฐาน EN 1992-1-1 {c:en1992} ตามสมการที่ {eq:maturity} โดย s เป็นสัมประสิทธิ์ที่ขึ้นกับชนิดซีเมนต์ ค่า s ที่มาตรฐานกำหนดมีตั้งแต่ 0.20 สำหรับซีเมนต์ที่พัฒนากำลังเร็ว ถึง 0.38 สำหรับซีเมนต์ที่พัฒนากำลังช้า ค่าที่เกินช่วงนี้มากแสดงว่าการพัฒนากำลังช้ากว่าปกติ หรือมีความไม่สม่ำเสมอของการทดสอบหรือสภาวะบ่ม")
    b.eq("maturity", r"\beta_{cc}(t) = \exp\left\{ s\left[1-\left(\frac{28}{t}\right)^{1/2}\right]\right\}")
    b.h3("2.5.3 บริเวณรอยต่อ ผลของรูปทรงชิ้นทดสอบ และประสิทธิภาพการใช้ซีเมนต์")
    b.p("ITZ ที่มีความพรุนสูงและโมดูลัสต่ำเป็นจุดอ่อนของคอนกรีต ดังที่ Scrivener และคณะ (2004) {c:scrivener2004} อธิบายความเป็นมาของบริเวณนี้ และ Xiao และคณะ (2013) {c:xiao2013} วัดค่าใน RCA ในด้านรูปทรงชิ้นทดสอบ ชิ้นทรงเตี้ยอย่างบล็อกปูพื้นหนา 6 ซม. ได้รับการเสริมกำลังจากแรงเสียดทานที่ผิวแผ่นกด (platen restraint) ซึ่งทำให้ค่ากำลังอัดที่อ่านได้สูงกว่าชิ้นทรงลูกบาศก์ที่ใช้วัสดุเดียวกัน (ผู้วิจัยตั้งเป็นข้อสังเกตจากกลศาสตร์ ผลเชิงตัวเลขในงานนี้แสดงในหัวข้อ 4.6.2) การเปรียบเทียบกำลังอัดกับค่าของงานอื่นจึงต้องคำนึงถึงรูปทรงชิ้นทดสอบด้วย")
    b.p("ประสิทธิภาพการใช้ซีเมนต์อธิบายได้ด้วยดัชนีความเข้มข้นของวัสดุประสาน (binder intensity, bi) ตามสมการที่ {eq:bi} ซึ่ง Damineli และคณะ (2010) {c:damineli2010} เสนอไว้ พร้อมรายงานว่าคอนกรีตกำลังมากกว่า 50 MPa ทำให้ bi ได้ราว 5 kg m<sup>−3</sup> MPa<sup>−1</sup> ขณะที่คอนกรีตกำลังต่ำอยู่ที่ 10–20 ค่านี้ใช้เทียบประสิทธิภาพของสูตรผสมในบทที่ 4")
    b.eq("bi", r"bi = \frac{B}{f_{c}}")

    # ------------------------------------------------ 2.6
    b.h2("2.6 ความต้านทานการลื่นไถลของพื้นผิว")
    b.p("แรงเสียดทานระหว่างยางและพื้นผิวแข็งที่หยาบเกิดจากสองกลไก คือการยึดเกาะที่ผิวสัมผัส (adhesion) และการสูญเสียพลังงานเมื่อยางเสียรูปตามความขรุขระของผิว (hysteresis) Persson (2001) {c:persson2001} อธิบายว่าเมื่อยางไถลบนพื้นผิวหยาบ ปุ่มนูนของผิวส่งแรงกระเพื่อมเข้าสู่ยาง และพลังงานสูญเสียผ่านแรงเสียดทานภายในของยาง ขึ้นกับสเปกตรัมความหยาบและความเร็วในการไถล ส่วน Persson และคณะ (2005) {c:persson2005} ทบทวนลักษณะความหยาบแบบ self-affine และบทบาทต่อการสัมผัสและแรงเสียดทาน Chang และคณะ (2001) {c:chang2001} สรุปกลไกแรงเสียดทานที่ผิวสัมผัสรองเท้ากับพื้นและนิยามเงื่อนไขการทดสอบสำหรับการวัดความลื่น ดังสรุปใน{fig:slipmech}")
    b.fig("slipmech", fp("s_slip_mech"), 14.0, "(ก) กลไกแรงเสียดทานของยางสไลเดอร์บนพื้นผิวหยาบ (ข) ปัจจัยที่กำหนดค่า BPN ของบล็อกปูพื้น (ผู้วิจัยสังเคราะห์จาก {c:persson2001,chang2001,gierasimiuk2021})")
    b.p("เครื่องทดสอบลูกตุ้มเป็นอุปกรณ์แบบกระแทก ใช้ยางสไลเดอร์ที่ปลายแขนเหวี่ยงผ่านผิวทดสอบและวัดพลังงานที่สูญเสีย ค่าที่อ่านได้ยิ่งสูง แรงเสียดทานยิ่งมาก ASTM E303-22 {c:astme303} ใช้ได้ทั้งภาคสนามและห้องปฏิบัติการ ระบุว่าเป็นการวัดแรงเสียดทานที่สัมพันธ์กับ microtexture และไม่ได้อ้างว่าให้ผลตรงกับวิธีวัดอื่น ผลของ macrotexture ต่อการลื่นขณะเปียกจึงต้องประเมินแยก เช่น ด้วยค่า MPD ตามที่ Gierasimiuk และคณะ (2021) {c:gierasimiuk2021} ทำในการเปรียบเทียบผิวคอนกรีตห้าแบบ และ Yuan และคณะ (2025) {c:yuan2025} พบว่าการฝังหินเกล็ดที่ผิวช่วยเพิ่มทั้งความต้านทานการลื่นไถลและการสึกหรอ")
    b.p("สำหรับบล็อกปูพื้นที่ใช้วัสดุเหลือทิ้ง Rodríguez และคณะ (2017) {c:rodriguez2017} ทดสอบความต้านทานการลื่นไถลและการสึกหรอของบล็อกที่ใช้มวลรวมรีไซเคิลเชิงอุตสาหกรรม และ Wang และคณะ (2019) {c:wangx2019} รายงานว่ายางบดทำให้สมบัติของบล็อกแย่ลง ยกเว้นความต้านทานการลื่นไถล แต่แหล่งข้อมูลที่ตรวจสอบได้ไม่ระบุวิธีทดสอบและค่าตัวเลข จึงยังเทียบค่า BPN กับงานเหล่านี้ไม่ได้")
    b.p("ปัจจัยของส่วนผสมที่น่าจะกำหนดค่า BPN ของงานนี้มี 3 ประการ ประการแรกคือความแข็งและความเหลี่ยมมุมของทรายและ RCA ที่ผิวบล็อก ซึ่งเป็นตัวสร้าง microtexture ประการที่สองคืออนุภาคไบโอชาร์ซึ่งเป็นคาร์บอนอ่อนและละเอียด อาจเติมช่องว่างระหว่างเม็ดทรายและทำให้ผิวเรียบขึ้นเมื่อสึกหรอ และประการที่สามคือความพรุนและการดูดซึมน้ำที่เปลี่ยนความเสียดทานเมื่อเปียก ทั้งสามข้อเป็นสมมติฐาน (H3) ที่ต้องทดสอบด้วยข้อมูลที่วัดจริง")

    # ------------------------------------------------ 2.7
    b.h2("2.7 หลักการประเมินวัฏจักรชีวิต")
    b.p("การประเมินวัฏจักรชีวิต (LCA) ตาม ISO 14040 {c:iso14040} และ ISO 14044 {c:iso14044} แบ่งเป็น 4 ขั้นตอน คือ การกำหนดเป้าหมายและขอบเขต การทำบัญชีรายการ (LCI) การประเมินผลกระทบ (LCIA) และการแปลผล ดังแสดงใน{fig:lcastages} งานนี้เลือกหน่วยหน้าที่เป็นบล็อกคอนกรีต 1 ลูกบาศก์เมตร และขอบเขตแบบ cradle-to-gate เช่นเดียวกับ Pizoń และคณะ (2026) {c:pizon2026} เพื่อให้เปรียบเทียบผลได้")
    b.fig("lcastages", fp("s_lca_stages"), 13.0, "กรอบการประเมินวัฏจักรชีวิตตาม ISO 14040/14044 (ผู้วิจัยวาดใหม่จาก {c:iso14040,iso14044})")
    b.p("ตัวชี้วัดผลกระทบที่ใช้กันมากที่สุดคือศักยภาพการทำให้โลกร้อน (GWP) ในรอบ 100 ปี ซึ่งคำนวณจากมวลของแต่ละวัสดุคูณตัวประกอบการปล่อยดังสมการที่ {eq:gwp} ชุดวิธี ReCiPe 2016 {c:huijbregts2017} ให้ 17 หมวดผลกระทบระดับ midpoint และฐานข้อมูล ecoinvent v3 {c:wernet2016} เป็นแหล่งข้อมูลบัญชีรายการที่ Pizoń และคณะใช้ อย่างไรก็ตาม รายงานนี้ไม่มีสิทธิ์เข้าถึงฐานข้อมูลดังกล่าว จึงคำนวณเฉพาะ GWP ด้วยตัวประกอบระดับคัดกรอง")
    b.eq("gwp", r"GWP = \sum_{i} m_{i}\,EF_{i}")
    b.p("สำหรับวัสดุที่เป็นของเสีย กฎ cut-off ของ ecoinvent ให้วัสดุรีไซเคิลเข้าสู่ระบบโดยไม่มีภาระจากวัฏจักรชีวิตก่อนหน้า {c:pizon2026} RCA จากห้องปฏิบัติการจึงมีภาระเฉพาะการบดย่อย ส่วนไบโอชาร์ถือว่าชีวมวลตั้งต้นเป็นของเหลือทิ้ง ภาระที่นับคือกระบวนการไพโรไลซิส ประเด็นที่ยังถกเถียงคือการให้เครดิตคาร์บอนที่กักเก็บในไบโอชาร์ งานของ Wang และคณะ (2026) {c:wangd2026} ให้ค่าสุทธิของไบโอชาร์เป็นลบเมื่อรวมการกู้คืนพลังงานและการกักเก็บ ส่วน Knoeri และคณะ (2013) {c:knoeri2013} แสดงว่าคอนกรีตมวลรวมรีไซเคิลมี GWP เท่ากับคอนกรีตทั่วไปเมื่อต้องเพิ่มซีเมนต์เกิน 22–40 kg/m<sup>3</sup> รายงานนี้จึงแสดงผลสองกรณี คือไม่ให้เครดิต (กรณี A ซึ่งเป็นกรณีฐาน) และให้เครดิตการกักเก็บ (กรณี B) และใช้ ci ตามสมการที่ {eq:ci} เป็นดัชนีเปรียบเทียบที่รวมกำลังอัดเข้ากับคาร์บอน")
    b.eq("ci", r"ci = \frac{GWP}{f_{c}}")

    # ------------------------------------------------ 2.8
    b.h2("2.8 การสังเคราะห์งานวิจัยที่เกี่ยวข้องเชิงระบบ")
    b.h3("2.8.1 วิธีการคัดเลือกและขอบเขตของหลักฐาน")
    b.p("การทบทวนครั้งนี้เป็นการทบทวนแบบมีโครงสร้างที่เน้นความตรวจสอบย้อนกลับได้ ไม่ใช่การทบทวนเชิงระบบเต็มรูปแบบตาม PRISMA ผู้วิจัยค้นหางานด้วยคำสำคัญ 6 กลุ่ม คือ biochar cement/concrete, bamboo biochar, recycled concrete aggregate, concrete paving block, pendulum slip/skid resistance และ LCA ของคอนกรีต โดยค้นผ่านเครื่องมือค้นหาเว็บ เนื่องจากไม่สามารถเข้าถึงฐานข้อมูลบรรณานุกรมโดยตรงและมีโควตาการค้นหาจำกัด เกณฑ์คัดเลือก ได้แก่ เป็นบทความที่ตีพิมพ์ในวารสารหรือเอกสารมาตรฐาน ยืนยันได้ว่ามีอยู่จริงจากผลการค้นหา เกี่ยวข้องกับตัวแปรของงานนี้โดยตรง และเน้นปี ค.ศ. 2018–2026 ยกเว้นงานพื้นฐานที่จำเป็น ตัวเลขทุกค่าในตารางที่ {tab:sys} มาจากบทคัดย่อหรือข้อความสรุปที่เห็นในผลการค้นหา และบางส่วนผ่านการสรุปของเครื่องมือค้นหา ควรตรวจสอบกับบทความฉบับเต็มก่อนอ้างอิงในบทความวิชาการ จึงไม่แสดงจำนวนบทความที่ค้นพบหรือคัดออก เพราะไม่มีบันทึกการค้นที่ครบถ้วนพอจะสร้างแผนภาพ PRISMA ได้")
    rows = []
    for th in "ABCD":
        rows.append([("__section__", sysrev.THEMES[th])])
        for r in [x for x in sysrev.ROWS if x[0] == th]:
            n = sum(1 for x in sysrev.ROWS if True and sysrev.ROWS.index(x) <= sysrev.ROWS.index(r))
            rows.append([str(n), "{c:" + r[1] + "}", r[2], r[3], r[4]])
    b.table("sys", "ตารางสังเคราะห์งานวิจัยที่เกี่ยวข้อง", ["ที่", "อ้างอิง", "วัสดุ/ระบบที่ศึกษา", "ระดับที่ศึกษา", "ผลที่รายงาน"], rows, [420, 700, 2300, 1300, 3950], align=["center", "center", "left", "left", "left"], sz=19,
            note="หมายเหตุ ตัวเลขสรุปจากบทคัดย่อ/ข้อความที่ตรวจพบ ไม่ใช่การอ่านฉบับเต็ม")
    b.h3("2.8.2 แผนที่หลักฐานและช่องว่างงานวิจัย")
    b.p("{fig:evmap} สรุปการกระจายของงานในตารางที่ {tab:sys} ตามหัวข้อ ช่วงเวลา และตัวแปรที่ศึกษา พบว่างานด้านไบโอชาร์และ RCA มีจำนวนมาก ขณะที่งานที่วัดความต้านทานการลื่นไถลของบล็อกปูพื้นที่ใช้วัสดุเหลือทิ้งและงานที่เชื่อมกลศาสตร์ของความพรุนเข้ากับผลการทดสอบมีน้อยที่สุด")
    b.fig("evmap", fp("s_evidence_map"), 14.5, "แผนที่หลักฐานของงานวิจัยในตารางสังเคราะห์: (ก) จำนวนตามหัวข้อ (ข) ตามช่วงปีที่ตีพิมพ์ (ค) ตามตัวแปรที่ศึกษา เทียบกับงานนี้")
    b.p("{fig:gap} เปรียบเทียบงานที่เลือกกับตัวแปรหกด้านของงานนี้ เครื่องหมายทึบหมายถึงตัวแปรนั้นปรากฏในข้อมูลที่สกัดได้ เครื่องหมายว่างหมายถึงไม่พบในข้อมูลที่สกัดได้ ซึ่งไม่ได้พิสูจน์ว่างานนั้นไม่ได้ศึกษาตัวแปรดังกล่าว")
    b.fig("gap", fp("s_gap_matrix"), 12.5, "เมทริกซ์ช่องว่างงานวิจัย: ตัวแปรที่แต่ละงานครอบคลุมเทียบกับงานนี้")
    b.h3("2.8.3 สรุปและช่องว่างที่งานนี้ศึกษา")
    b.p("จากการสังเคราะห์สรุปได้ 4 ประการ (1) ผลของไบโอชาร์ต่อกำลังขึ้นกับปริมาณ โดยมักได้ประโยชน์ที่ระดับต่ำ (ประมาณร้อยละ 1–6) และกำลังลดเมื่อทดแทนซีเมนต์สูงกว่านั้น แต่ไบโอชาร์ที่มีสมบัติเหมาะสมอาจทดแทนได้ถึงร้อยละ 10 {c:hylton2024,legan2025} (2) RCA ในบล็อกปูพื้นทดแทนได้ในระดับร้อยละ 15–60 ขึ้นกับขนาดอนุภาคและเกณฑ์ที่ใช้ {c:wangx2019,contreras2022,rodriguez2017} (3) ข้อมูลความต้านทานการลื่นไถลของบล็อกปูพื้นที่ใช้วัสดุเหลือทิ้งแทบไม่มีค่าตัวเลขที่ตรวจสอบได้ (4) LCA ของคอนกรีตทุกงานชี้ว่าซีเมนต์เป็นตัวขับ GWP หลัก ผลการลดซีเมนต์จึงเป็นกุญแจ {c:pizon2026,wangd2026}")
    b.p("ช่องว่างที่งานนี้ศึกษาคือการนำไบโอชาร์ไม้ไผ่และ RCA จากห้องปฏิบัติการมาใช้ในบล็อกปูพื้นแบบอัดแน่นพร้อมกัน แล้วประเมินสมบัติกลและกายภาพตามมาตรฐาน ความต้านทานการลื่นไถล และคาร์บอนเบื้องต้นในกรอบเดียวกัน โดยใช้กลศาสตร์ของความพรุนและการพัฒนากำลังอธิบายผล ข้อจำกัดของข้อสรุปนี้คือการค้นหามีขอบเขตจำกัดตามที่ระบุในหัวข้อ 2.8.1")
